  async function commonsImageResults(query){
    const cacheKey=`commons:${query.toLocaleLowerCase()}`;if(imageCache.has(cacheKey))return imageCache.get(cacheKey);
    const params=new URLSearchParams({action:'query',generator:'search',gsrsearch:query,gsrnamespace:'6',gsrlimit:'4',prop:'imageinfo',iiprop:'url|extmetadata',iiurlwidth:'320',format:'json',origin:'*'});
    const response=await fetch(`https://commons.wikimedia.org/w/api.php?${params}`);if(!response.ok)throw new Error(`Wikimedia Commons HTTP ${response.status}`);
    const data=await response.json(),pages=Object.values(data.query?.pages||{});const items=pages.map(page=>{const info=page.imageinfo?.[0];return {src:info?.thumburl||info?.url,href:`https://commons.wikimedia.org/wiki/${encodeURIComponent(page.title.replaceAll(' ','_'))}`,title:page.title.replace(/^File:/,'')+' · Wikimedia Commons'}}).filter(item=>item.src&&item.href);imageCache.set(cacheKey,items);return items;
  }


