    const response=await fetch(`https://clinicaltables.nlm.nih.gov/api/conditions/v3/search?${params}`,{headers:{Accept:'application/json'},cache:'no-cache'});if(!response.ok)throw new Error(`ClinicalTables HTTP ${response.status}`);
