      const summaryDetails=document.createElement('details');summaryDetails.className='condition-inline-summary';summaryDetails.dataset.conditionTitle=topic.primaryName||topic.title;const summaryLabel=document.createElement('summary'),summaryHeading=document.createElement('strong'),summaryPreview=document.createElement('span');summaryHeading.textContent=t('conditionInlineSummary');summaryPreview.className='condition-inline-preview';summaryPreview.textContent=t('conditionSummaryLoading');summaryLabel.append(summaryHeading,summaryPreview);const summaryBody=document.createElement('div');summaryBody.className='condition-inline-summary-body';summaryDetails.append(summaryLabel,summaryBody);summaryDetails.addEventListener('toggle',()=>{if(summaryDetails.open&&summaryDetails.dataset.loaded!=='true')loadConditionCardSummary(summaryDetails)});card.append(summaryDetails);
