  const wikipediaConditionCache=new Map();
  async function fetchWikipediaCondition(topic){
    const term=topic.primaryName||topic.title,cacheKey=`${language}:${clean(term)}`;if(wikipediaConditionCache.has(cacheKey))return wikipediaConditionCache.get(cacheKey);
    const candidates=language==='ar'?[['ar',topic.title],['en',term]]:[['en',term],['ar',topic.title]];
    for(const [project,query] of candidates){
      try{
        const params=new URLSearchParams({action:'query',generator:'search',gsrsearch:query,gsrnamespace:'0',gsrlimit:'1',prop:'extracts|info',explaintext:'1',exsectionformat:'wiki',inprop:'url',redirects:'1',format:'json',origin:'*'});
        const response=await fetch(`https://${project}.wikipedia.org/w/api.php?${params}`,{headers:{'Api-User-Agent':'Dawaya/1.0 (Egyptian condition guide)'}});if(!response.ok)continue;
        const json=await response.json(),page=Object.values(json.query?.pages||{}).find(item=>item.extract);if(!page)continue;
        const sections={overview:'',symptoms:'',causes:'',diagnosis:'',treatment:'',complications:'',prevention:'',prognosis:''};let current='overview';
        const assignSection=heading=>{const h=clean(heading);if(/symptom|sign|clinical presentation|الاعراض|علامات/.test(h))return 'symptoms';if(/diagnos|test|screen|evaluation|التشخيص|الفحوص|الاختبارات/.test(h))return 'diagnosis';if(/treat|management|therapy|care|علاج|التدبير|الرعاية/.test(h))return 'treatment';if(/cause|risk factor|etiology|سبب|اسباب|عامل خطر|عوامل الخطورة/.test(h))return 'causes';if(/complication|مضاعف/.test(h))return 'complications';if(/prevention|prevent|وقاية/.test(h))return 'prevention';if(/prognos|outlook|مآل|توقعات/.test(h))return 'prognosis';if(/introduction|overview|definition|background|مقدمة|نظرة عامة|تعريف/.test(h))return 'overview';return null};
        for(const line of String(page.extract).split(/\n+/)){const heading=line.match(/^={2,5}\s*(.*?)\s*={2,5}$/);if(heading){current=assignSection(heading[1])||'other';continue}if(current!=='other'&&line.trim()){const text=line.trim();sections[current]=(sections[current]?sections[current]+'\n':'')+text}}
        if(!sections.overview.trim()){const lead=String(page.extract).split(/\n={2,}/)[0].trim();sections.overview=lead}
        const data={title:page.title,url:page.fullurl||`https://${project}.wikipedia.org/?curid=${page.pageid}`,sections,project};wikipediaConditionCache.set(cacheKey,data);return data;
      }catch(error){console.warn('Wikipedia condition lookup failed:',error)}
    }
    const missing=null;wikipediaConditionCache.set(cacheKey,missing);return missing;
  }
