  function openGoogleImages(drug){
    const query=[brandEn(drug),val(drug,'scientific_name'),val(drug,'manufacturer'),'medicine Egypt'].filter(Boolean).join(' ');
    openExternal(`https://www.google.com/search?tbm=isch&igu=1&q=${encodeURIComponent(query)}`,language==='ar'?'صور Google':'Google Images');
  }
  async function loadMedicineThumbnail(button,query){
    try{const items=await googleImageResults(query);if(!items.length||!button.isConnected)return;const item=items[0],picture=button.querySelector('.medicine-picture');if(!picture)return;picture.classList.add('has-photo');picture.innerHTML=`<img src="${esc(item.src)}" alt="${esc(query)}" loading="lazy" referrerpolicy="no-referrer">`;if(button.id==='modalImageSearch')$('#modalImageCaption').innerHTML=`<a href="${esc(item.href)}" target="_blank" rel="noopener noreferrer">${esc(item.title)}</a>`}
    catch(error){console.warn('Google Images thumbnail unavailable:',error)}
  }
  async function triggerConditionImages(button){
    if(button.dataset.loaded==='true'||button.disabled)return;button.disabled=true;const gallery=button.parentElement?.querySelector('.condition-image-gallery');
    if(gallery){await renderImageGallery(gallery,`${button.dataset.imageQuery} symptoms diagnosis`);if(gallery.querySelector('.medical-image-result'))button.dataset.loaded='true'}
    button.disabled=false;
  }
  async function renderImageGallery(container,query){
    container.innerHTML=`<p class="image-loading">${language==='ar'?'جارٍ تحميل الصور…':'Loading image references…'}</p>`;
    try{const items=await googleImageResults(query);if(!items.length){container.innerHTML=`<p class="image-loading">${language==='ar'?'لا توجد صور لهذا البحث.':'No image results for this search.'}</p>`;return}
      container.innerHTML=items.map(item=>`<a class="medical-image-result" href="${esc(item.href)}" target="_blank" rel="noopener noreferrer"><img src="${esc(item.src)}" alt="${esc(item.title)}" loading="lazy" referrerpolicy="no-referrer"><span>${esc(item.title)}</span></a>`).join('');
    }catch(error){container.innerHTML=`<p class="image-loading">${language==='ar'?'تعذر تحميل الصور. تحقق من إعدادات Google.':'Images unavailable. Check Google image setup and API quota.'}</p>`;console.warn('Google Images gallery unavailable:',error)}
  }
  function openDrug(drug){
    activeDrug=drug;
    const en=brandEn(drug),ar=val(drug,'commercial_name_ar'),sci=val(drug,'scientific_name'),cls=val(drug,'drug_class'),maker=val(drug,'manufacturer'),route=val(drug,'route'),price=priceText(drug),notes=findClinicalNotes(drug);
    $('#modalTitle').textContent=(language==='ar'?(ar||en):(en||ar))||t('medicine');$('#modalEnglish').textContent=language==='ar'?en:sci||'';$('#modalArabic').textContent=language==='en'?ar:'';$('#modalClass').textContent=cls||t('classificationMissing');$('#modalManufacturer').textContent=maker||'';
    $('#modalFacts').innerHTML=`<div class="fact"><span>${esc(t('activeIngredient'))}</span><b>${esc(sci||t('notListed'))}</b></div><div class="fact"><span>${esc(t('route'))}</span><b>${esc(routeLabel(route))}</b></div><div class="fact"><span>${esc(t('listedPrice'))}</span><b>${price?`${esc(Number(price).toLocaleString(language==='ar'?'ar-EG':'en-US'))} ${language==='ar'?'ج.م':'EGP'}`:esc(t('notAvailable'))}</b></div>`;
    $('#modalImage').innerHTML=medicineIllustration(drug);$('#modalImagePanel').hidden=false;
    $('#modalImageSearch').onclick=()=>openGoogleImages(drug);$('#modalImageShowImages').onclick=()=>openGoogleImages(drug);
    $('#modalImageCaption').textContent=productImageUrl(drug)?t('productPhoto'):t('illustrativeImage');
    const imageElement=$('#modalImage img');if(imageElement)imageElement.addEventListener('error',()=>{imageElement.remove();$('#modalImage .photo-fallback').hidden=false;$('#modalImageCaption').textContent=t('illustrativeImage')},{once:true});
    if(!productImageUrl(drug))loadMedicineThumbnail($('#modalImageSearch'),`${en} ${sci} medicine`.trim());
    if(notes){
      $('#overviewPanel').innerHTML=`<section class="detail-block"><h3>${esc(t('howWorks'))}</h3><p class="detail-lead">${esc(clinicalText(notes,'mechanism'))}</p></section><section class="detail-block"><h3>${esc(t('pharmacology'))}</h3><p>${esc(clinicalText(notes,'pharmacology'))}</p></section>`;
      $('#usePanel').innerHTML=`<section class="detail-block"><h3>${esc(t('commonUse'))}</h3><p>${esc(clinicalText(notes,'uses'))}</p></section><section class="detail-block"><h3>${esc(t('sideEffects'))}</h3><p>${esc(clinicalText(notes,'effects'))}</p></section><section class="detail-block"><h3>${esc(t('howGiven'))}</h3><p>${esc(t('databaseRouteProduct'))}: <b>${esc(routeLabel(route))}</b>. ${esc(t('routeInstruction'))}</p></section>`;
      $('#cautionPanel').innerHTML=`<div class="no-clinical">${esc(clinicalText(notes,'safety'))}</div><p style="margin-top:12px">${esc(t('leafletAdvice'))}</p><a class="source-link" target="_blank" rel="noreferrer" href="https://dailymed.nlm.nih.gov/dailymed/search.cfm?query=${encodeURIComponent(sci||en)}">${esc(t('searchOfficialLabels'))} <span>↗</span></a>`;
    }else{
      const classification=cls?`${t('sourceClassificationLead')} “${cls}.” ${t('classLimits')}`:t('missingMonograph');
      $('#overviewPanel').innerHTML=`<section class="detail-block"><h3>${esc(t('howWorks'))}</h3><p class="detail-lead">${esc(classification)}</p></section><section class="detail-block"><h3>${esc(t('activeIngredient'))}</h3><p>${esc(sci||t('ingredientNotAvailable'))}</p></section><div class="no-clinical">${esc(t('noVerifiedMechanism'))}</div>`;
      $('#usePanel').innerHTML=`<div class="no-clinical">${esc(t('routeOnly'))} “${esc(routeLabel(route))}.” ${esc(t('noInstructions'))}</div>`;
      $('#cautionPanel').innerHTML=`<div class="no-clinical">${esc(t('safeUse'))}</div>`;
    }
    $('#overviewPanel').insertAdjacentHTML('beforeend',`<section class="wiki-summary detail-block"><h3>${language==='ar'?'ملخص من ويكيبيديا':'Wikipedia overview'}</h3><div id="wikiDrugSummary">${language==='ar'?'جارٍ تحميل الملخص…':'Loading encyclopedia summary…'}</div></section>`);
    loadWikipediaSummary(drug,sci||en);
    document.querySelectorAll('.detail-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.panel==='overview'));
    ['overview','use','caution'].forEach(panel=>$('#'+panel+'Panel').hidden=panel!=='overview');modal.hidden=false;document.body.style.overflow='hidden';$('#modalClose').focus();
  }
  function closeModal(){modal.hidden=true;document.body.style.overflow='';activeDrug=null;}
  async function loadWikipediaSummary(drug,query){const box=$('#wikiDrugSummary');if(!box)return;try{const cacheKey=`${language}:${clean(query)}`;let data=wikiCache.get(cacheKey);if(!data){data={extract:''};const projects=language==='ar'?['ar','en']:['en'];for(const project of projects){const params=new URLSearchParams({action:'query',generator:'search',gsrsearch:query,gsrnamespace:'0',gsrlimit:'1',prop:'extracts',exintro:'1',explaintext:'1',format:'json',origin:'*'});const response=await fetch(`https://${project}.wikipedia.org/w/api.php?${params}`,{headers:{'Api-User-Agent':'Dawaya/1.0 (Egyptian medicine guide)'}});if(!response.ok)throw new Error(`Wikipedia HTTP ${response.status}`);const json=await response.json();const page=Object.values(json.query?.pages||{}).find(item=>item.extract);if(page){data={title:page.title,extract:page.extract,url:`https://${project}.wikipedia.org/?curid=${page.pageid}`};break}}wikiCache.set(cacheKey,data)}if(activeDrug!==drug)return;box.innerHTML=data.extract?`<p>${esc(data.extract)}</p><a href="${esc(data.url)}" target="_blank" rel="noreferrer">${language==='ar'?'المصدر: ويكيبيديا':'Source: Wikipedia'} — ${esc(data.title)} ↗</a><small>${language==='ar'?'ملخص موسوعي عام؛ راجع النشرة المعتمدة':'General encyclopedia summary; consult the approved product leaflet.'}</small>`:`<p>${language==='ar'?'لم يتوفر ملخص مطابق في ويكيبيديا.':'No matching Wikipedia summary was found.'}</p>`}catch(error){if(activeDrug===drug)box.textContent=language==='ar'?'تعذر تحميل ملخص ويكيبيديا.':'Wikipedia summary is unavailable right now.';console.warn('Wikipedia medicine summary unavailable:',error)}}

  input.addEventListener('input',()=>{activeSuggestion=-1;clearTimeout(debounce);clearTimeout(unifiedConditionTimer);debounce=setTimeout(()=>{search();renderSuggestions(false)},100);unifiedConditionTimer=setTimeout(updateUnifiedConditionSearch,180)});
