    if(event.key==='ArrowUp'&&options.length){event.preventDefault();conditionSuggestionActive=(conditionSuggestionActive-1+options.length)%options.length;options.forEach((option,index)=>{option.classList.toggle('active',index===conditionSuggestionActive);option.setAttribute('aria-selected',String(index===conditionSuggestionActive))});options[conditionSuggestionActive].scrollIntoView({block:'nearest'});return}
