  const drawer=$('#drawerBackdrop');function closeDrawer(){drawer.hidden=true;$('#menuToggle').setAttribute('aria-expanded','false')};$('#menuToggle').addEventListener('click',()=>{drawer.hidden=false;$('#menuToggle').setAttribute('aria-expanded','true')});$('#menuClose').addEventListener('click',closeDrawer);drawer.addEventListener('click',event=>{if(event.target===drawer)closeDrawer()});document.querySelectorAll('[data-drawer-action]').forEach(button=>button.addEventListener('click',event=>{const action=button.dataset.drawerAction;closeDrawer();if(action==='unified-search'){switchPage('medicines','home');input.focus()}else if(action==='medicine-list'){switchPage('medicines','medicine-list');$('#medicineAlphabet').scrollIntoView({behavior:'smooth',block:'center'})}else if(action==='condition-list'){switchPage('conditions','condition-list');$('#conditionGroups').scrollIntoView({behavior:'smooth',block:'center'})}else if(action==='about')switchPage('about','about');else if(action==='suggestions'){switchPage('suggestions','suggestions');$('#suggestionEmail').focus()}}));
